  let depth = 0;
  let prev = 'start';
  for (const c of t) {
    if (c >= '0' && c <= '9') {
      if (prev === 'close') return -1;
      prev = 'num';
    } else if (c === '+' || c === '-') {
      if (prev !== 'num' && prev !== 'close') return -1;
      prev = 'op';
    } else if (c === '(') {
