      depth--;
      if (depth < 0) return -1;
      prev = 'close';
    } else {
      return -1;
    }
  }
  if (prev !== 'num' && prev !== 'close') return -1;
  if (depth !== 0) return -1;

  const MOD = 1000000007;
  const norm = (x) => ((x % MOD) + MOD) % MOD;

  const evaluate = (part) => {
    let res = 0;
    let sign = 1;
    let num = 0;
    let i = 0;
    while (i < part.length) {
      const c = part[i];
      if (c >= '0' && c <= '9') {
        num = (num * 10 + (c.charCodeAt(0) - 48)) % MOD;
