            if (d === 0) break;
          }
          j++;
        }
        res = norm(res + sign * num);
        num = 0;
        res = norm(res + sign * evaluate(part.slice(i + 1, j)));
        sign = 1;
        i = j + 1;
      }
    }
    return norm(res + sign * num);
  };

